import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type Status = 'ok' | 'risk' | 'over';

type Project = {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: Status;
};

const PAGE_SIZE = 5;

const STATUS_ORDER: Status[] = ['ok', 'risk', 'over'];

const STATUS_LABEL: Record<Status, string> = {
  ok: 'В норме',
  risk: 'Под риском',
  over: 'Превышение',
};

const STATUS_COLOR: Record<Status, string> = {
  ok: 'var(--jx-success)',
  risk: 'var(--jx-warning)',
  over: 'var(--jx-danger)',
};

const PROJECTS: Project[] = [
  { id: 'atlas', name: 'Atlas Migration', spent: 4200, quota: 12000, status: 'ok' },
  { id: 'beacon', name: 'Beacon Analytics', spent: 9100, quota: 10000, status: 'risk' },
  { id: 'cobalt', name: 'Cobalt Billing', spent: 15400, quota: 11000, status: 'over' },
  { id: 'delta', name: 'Delta Ingest', spent: 2600, quota: 8000, status: 'ok' },
  { id: 'ember', name: 'Ember Search', spent: 7300, quota: 9000, status: 'risk' },
  { id: 'flux', name: 'Flux Notifications', spent: 1200, quota: 6000, status: 'ok' },
  { id: 'grove', name: 'Grove Identity', spent: 8800, quota: 9500, status: 'risk' },
  { id: 'halo', name: 'Halo Media', spent: 13200, quota: 9000, status: 'over' },
  { id: 'iris', name: 'Iris Reporting', spent: 3400, quota: 10000, status: 'ok' },
  { id: 'juno', name: 'Juno Scheduler', spent: 5600, quota: 7000, status: 'risk' },
  { id: 'kilo', name: 'Kilo Storage', spent: 18700, quota: 14000, status: 'over' },
  { id: 'lumen', name: 'Lumen Gateway', spent: 900, quota: 5000, status: 'ok' },
  { id: 'nova', name: 'Nova Experiments', spent: 6400, quota: 20000, status: 'ok' },
];

export default function ProjectSpendPanel() {
  const [active, setActive] = useState<Status[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => active.includes(project.status)),
    [active],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const rows = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const toggle = (status: Status) => {
    setActive((current) =>
      current.includes(status)
        ? current.filter((item) => item !== status)
        : [...current, status],
    );
    setPage(1);
  };

  const reset = () => {
    setActive(STATUS_ORDER);
    setPage(1);
  };

  return (
    <section
      className="jx-card"
      aria-label="Расход по проектам"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2, 8px)' }}>
        <h2 className="jx-heading" style={{ margin: 0 }}>
          Расход по проектам
        </h2>
        <div
          role="group"
          aria-label="Фильтр по статусу"
          style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
        >
          {STATUS_ORDER.map((status) => {
            const isActive = active.includes(status);
            return (
              <button
                key={status}
                type="button"
                className="jx-chip"
                aria-pressed={isActive}
                onClick={() => toggle(status)}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 'var(--jx-space-1, 6px)',
                  borderColor: isActive ? STATUS_COLOR[status] : 'var(--jx-border)',
                  color: isActive ? 'var(--jx-fg)' : 'var(--jx-fg-muted)',
                }}
              >
                <span
                  aria-hidden="true"
                  style={{
                    width: 'var(--jx-space-2, 8px)',
                    height: 'var(--jx-space-2, 8px)',
                    borderRadius: 'var(--jx-radius-full, 999px)',
                    background: STATUS_COLOR[status],
                  }}
                />
                {STATUS_LABEL[status]}
                {isActive ? <span aria-hidden="true">×</span> : null}
              </button>
            );
          })}
        </div>
      </header>

      {rows.length === 0 ? (
        <div
          className="jx-empty"
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 'var(--jx-space-3, 12px)',
            padding: 'var(--jx-space-6, 24px)',
            textAlign: 'center',
          }}
        >
          <p className="jx-text-muted" style={{ margin: 0 }}>
            Под выбранные фильтры не попал ни один проект.
          </p>
          <Button onClick={reset}>Сбросить фильтры</Button>
        </div>
      ) : (
        <>
          <ul
            className="jx-list"
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--jx-space-2, 8px)',
            }}
          >
            {rows.map((project) => {
              const percent = Math.round((project.spent / project.quota) * 100);
              const arc = Math.min(percent, 100);
              return (
                <li
                  key={project.id}
                  className="jx-list-item"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--jx-space-3, 12px)',
                    padding: 'var(--jx-space-3, 12px)',
                  }}
                >
                  <svg
                    viewBox="0 0 40 40"
                    width="40"
                    height="40"
                    role="img"
                    aria-label={`Квота использована на ${percent} процентов`}
                    style={{ flex: '0 0 auto' }}
                  >
                    <circle
                      cx="20"
                      cy="20"
                      r="16"
                      fill="none"
                      stroke="var(--jx-border)"
                      strokeWidth="4"
                    />
                    <circle
                      cx="20"
                      cy="20"
                      r="16"
                      fill="none"
                      stroke={STATUS_COLOR[project.status]}
                      strokeWidth="4"
                      pathLength={100}
                      strokeDasharray={`${arc} ${100 - arc}`}
                      transform="rotate(-90 20 20)"
                    />
                    <text
                      x="20"
                      y="20"
                      textAnchor="middle"
                      dominantBaseline="central"
                      fill="var(--jx-fg)"
                      fontSize="11"
                    >
                      {percent}
                    </text>
                  </svg>

                  <div style={{ flex: '1 1 auto', minWidth: 0 }}>
                    <div style={{ fontWeight: 600 }}>{project.name}</div>
                    <div className="jx-text-muted" style={{ fontSize: 'var(--jx-font-sm, 0.85em)' }}>
                      {project.spent.toLocaleString('ru-RU')} из{' '}
                      {project.quota.toLocaleString('ru-RU')}
                    </div>
                  </div>

                  <span
                    className="jx-badge"
                    style={{
                      flex: '0 0 auto',
                      borderColor: STATUS_COLOR[project.status],
                      color: STATUS_COLOR[project.status],
                    }}
                  >
                    {STATUS_LABEL[project.status]}
                  </span>
                </li>
              );
            })}
          </ul>

          <nav
            aria-label="Постраничная навигация"
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 'var(--jx-space-3, 12px)',
            }}
          >
            <Button
              onClick={() => setPage((current) => Math.max(1, current - 1))}
              disabled={safePage === 1}
            >
              Назад
            </Button>
            <span className="jx-text-muted" aria-live="polite">
              Страница {safePage} из {totalPages} · {filtered.length} проектов
            </span>
            <Button
              onClick={() => setPage((current) => Math.min(totalPages, current + 1))}
              disabled={safePage === totalPages}
            >
              Вперёд
            </Button>
          </nav>
        </>
      )}
    </section>
  );
}

